package com.cvns.service;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.cvns.dtos.ResponseDtos.DashboardResponse;import com.cvns.entities.*;import com.cvns.entities.AppEnums.*;import com.cvns.repository.*;import com.cvns.security.SecurityUtils;import lombok.RequiredArgsConstructor;
@Service @Transactional(readOnly=true) @RequiredArgsConstructor public class DashboardService{private final SecurityUtils sec;private final ChildRepository children;private final VaccineRepository vaccines;private final VaccinationRecordRepository records;private final NotificationRepository notifications;private final AppointmentRepository appointments;public DashboardResponse dashboard(){User u=sec.currentUser();long upcoming=0,missed=0;for(Child c:children.findByParentIdOrderByNameAsc(u.getId()))for(Vaccine v:vaccines.findAllByOrderByDueAgeMonthsAscDoseNumberAsc()){var x=records.findByChildIdAndVaccineId(c.getId(),v.getId());if(x.isPresent()&&x.get().getStatus()==VaccinationStatus.COMPLETED)continue;LocalDate due=c.getDateOfBirth().plusMonths(v.getDueAgeMonths());if(due.isBefore(LocalDate.now()))missed++;else if(!due.isAfter(LocalDate.now().plusDays(30)))upcoming++;}long completed=records.countByChildParentIdAndStatus(u.getId(),VaccinationStatus.COMPLETED);long apps=appointments.countByBookedByIdAndAppointmentDateGreaterThanEqualAndStatusIn(u.getId(),LocalDate.now(),EnumSet.of(AppointmentStatus.BOOKED,AppointmentStatus.ACCEPTED));return new DashboardResponse(children.countByParentId(u.getId()),upcoming,missed,completed,notifications.countByRecipientIdAndReadFalse(u.getId()),apps);}}
